package com.hbm.machine.silex;
import com.google.gson.*;import com.hbm.recipe.generic.*;import com.hbm.registry.HbmItemTags;import com.mojang.logging.LogUtils;import java.util.*;import net.minecraft.core.HolderLookup;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.MinecraftServer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.neoforged.bus.api.EventPriority;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.OnDatapackSyncEvent;import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;

/** Whole original static recipe table and item/dict/tiny-waste translations; native multiplayer sync. */
public final class SilexRecipes {
 private record Translation(ItemStack from,ItemStack to){}
 private static final List<Translation> TRANSLATIONS=new ArrayList<>();private static final Map<String,String> TAG_TRANSLATIONS=new LinkedHashMap<>(),TINY_WASTE=new LinkedHashMap<>(),ALIASES=new LinkedHashMap<>();private static final List<String> UNRESOLVED=new ArrayList<>();private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();
 public static void register(){NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent event)->install(event.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent event)->{var server=event.getPlayerList().getServer();if(event.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<SilexRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(SilexContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
 /** Source getAllIngredients/getRecipes additionally exposes the four item aliases and two dictionary aliases. */
 public static List<ItemStack> examples(RecipeManager manager,SilexRecipe recipe){var result=new ArrayList<>(recipe.inputItems().getFirst().examples());for(var translation:TRANSLATIONS){var found=find(manager,translation.from);if(found!=null&&found.data()==recipe.data()&&result.stream().noneMatch(stack->same(stack,translation.from)))result.add(translation.from.copy());}for(var raw:TAG_TRANSLATIONS.keySet()){var variants=HbmItemTags.items(raw).toList();if(!variants.isEmpty()){var found=find(manager,variants.getFirst());if(found!=null&&found.data()==recipe.data())for(var stack:variants)if(result.stream().noneMatch(other->same(other,stack)))result.add(stack.copy());}}return result;}
 public static int metadata(ItemStack stack){return stack.getOrDefault(com.hbm.hazard.HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue());}
 public static boolean same(ItemStack a,ItemStack b){return !a.isEmpty()&&!b.isEmpty()&&a.is(b.getItem())&&metadata(a)==metadata(b);}
 public static ItemStack singular(ItemStack original){var stack=new ItemStack(original.getItem());if(original.has(com.hbm.hazard.HbmHazards.LEGACY_METADATA.get()))stack.set(com.hbm.hazard.HbmHazards.LEGACY_METADATA.get(),metadata(original));else if(original.isDamageableItem())stack.setDamageValue(original.getDamageValue());if(original.has(com.hbm.item.fluid.FluidItemContent.FLUID_TYPE.get()))stack.set(com.hbm.item.fluid.FluidItemContent.FLUID_TYPE.get(),original.get(com.hbm.item.fluid.FluidItemContent.FLUID_TYPE.get()));return stack;}
 public static SilexRecipe find(RecipeManager manager,ItemStack input){
  if(input.isEmpty())return null;ItemStack actual=singular(input);for(var translation:TRANSLATIONS)if(same(actual,translation.from)){actual=translation.to;break;}var recipes=recipes(manager);SilexRecipe direct=null;
  for(var recipe:recipes)if(HbmItemTags.tag(recipe.inputItems().getFirst().ingredient()).isEmpty()&&recipe.inputItems().getFirst().matches(actual,true))direct=recipe;
  if(direct!=null)return direct;
  for(String key:HbmItemTags.tags(actual)){String translated=TAG_TRANSLATIONS.getOrDefault(key,key);SilexRecipe match=null;for(var recipe:recipes)if(HbmItemTags.tag(recipe.inputItems().getFirst().ingredient()).filter(tag->tag.location().toString().equals(translated)).isPresent())match=recipe;if(match!=null)return match;}
  String item=BuiltInRegistries.ITEM.getKey(actual.getItem()).toString();if(TINY_WASTE.containsKey(item)){var whole=GenericRecipeConfigCodec.legacyStack(TINY_WASTE.get(item),metadata(actual),ALIASES);var recipe=find(manager,whole);return recipe==null?null:recipe.tiny();}return null;
 }
 private static JsonObject resource(String path){try(var stream=SilexRecipes.class.getResourceAsStream(path)){if(stream==null)throw new IllegalStateException("Missing source SILEX data "+path);return JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}catch(java.io.IOException error){throw new IllegalStateException(error);}}
 private static SilexRecipe read(JsonObject row){var input=GenericRecipeConfigCodec.readIngredient(row.getAsJsonArray("input"),ALIASES);var choices=new ArrayList<GenericOutput.Chance>();for(var value:row.getAsJsonArray("outputs")){var entry=value.getAsJsonObject();choices.add(new GenericOutput.Chance(GenericRecipeConfigCodec.readStack(entry.getAsJsonArray("stack"),ALIASES),1,entry.get("weight").getAsInt()));}int order=row.get("order").getAsInt();var data=new GenericRecipeData("silex."+order,100,0,List.of(input),List.of(),List.of(new GenericOutput(choices,true)),List.of(),List.of(),"",ItemStack.EMPTY,false,"",order);return new SilexRecipe(data,row.get("produced").getAsInt(),row.get("consumed").getAsInt(),LaserWavelength.valueOf(row.get("wavelength").getAsString()));}
 public static void setup(net.neoforged.fml.event.lifecycle.FMLCommonSetupEvent event){event.enqueueWork(SilexRecipes::loadTranslations);}
 private static synchronized void loadTranslations(){
  ALIASES.clear();resource("/hbm/silex-item-aliases.json").entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));var source=resource("/hbm/silex-source-recipes.json");TRANSLATIONS.clear();TAG_TRANSLATIONS.clear();TINY_WASTE.clear();UNRESOLVED.clear();
  for(var value:source.getAsJsonArray("itemTranslations"))try{var pair=value.getAsJsonArray();TRANSLATIONS.add(new Translation(GenericRecipeConfigCodec.readStack(pair.get(0).getAsJsonArray(),ALIASES),GenericRecipeConfigCodec.readStack(pair.get(1).getAsJsonArray(),ALIASES)));}catch(Exception error){UNRESOLVED.add("translation: "+error.getMessage());}
  for(var value:source.getAsJsonArray("tagTranslations")){var pair=value.getAsJsonArray();TAG_TRANSLATIONS.put(pair.get(0).getAsString(),pair.get(1).getAsString());}
  for(var value:source.getAsJsonArray("tinyWasteTranslations")){var pair=value.getAsJsonArray();TINY_WASTE.put(pair.get(0).getAsString(),pair.get(1).getAsString());}
 }
 private static void install(MinecraftServer server){loadTranslations();var source=resource("/hbm/silex-source-recipes.json");
  var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();
  for(var value:source.getAsJsonArray("recipes"))try{var row=value.getAsJsonObject();var recipe=read(row);var id=SilexContent.id("silex/default/"+row.get("order").getAsInt());additions.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){UNRESOLVED.add(value.getAsJsonObject().get("source")+": "+error.getMessage());}
  additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);if(!UNRESOLVED.isEmpty())LogUtils.getLogger().warn("{} source SILEX rows/translations await actual items; full source dependencies remain in hbm/silex-source-recipes.json",UNRESOLVED.size());
 }
 public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}private SilexRecipes(){}
}
